void calllog_dial_calls_key_event(uint32_t key,lv_obj_t * ui_Screen)
{
    ui_screen_calllog_dial_calls_obj_t * p_screen_param;
    lv_obj_t *      list = get_calllog_dial_calls_select_list_obj(ui_Screen);

    ;
    uint32_t        child_cnt = lv_obj_get_child_cnt(list);
    uint32_t        child_id = get_list_child_focused_id(list,child_cnt);
    lv_obj_t *      get_focus_obj = NULL;
    lv_obj_t *      pre_focus_obj = NULL;
    lv_obj_t *      label;
    lv_obj_t *      label2;
    uint8_t         str_buf[200];

    p_screen_param      = (ui_screen_calllog_dial_calls_obj_t *) lv_obj_get_user_data(ui_Screen);

    memset(str_buf,0,200);

    //__inf("sms_menu_key_event key:%d,child_id:%d,child_cnt:%d\r\n",key,child_id,child_cnt);
    switch (key)
    {
        case LV_KEY_UP:
            {
                if (child_cnt <= 1)
                    return;

                if (child_id != 0) {
                    pre_focus_obj       = lv_obj_get_child(list,child_id);
                    lv_obj_clear_state(pre_focus_obj,LV_STATE_FOCUSED);


                    get_focus_obj       = lv_obj_get_child(list,child_id - 1);
                    lv_obj_add_state(get_focus_obj,LV_STATE_FOCUSED);

                    if ((child_id - 1) == 0) {
                        lv_obj_scroll_to_y(list,0,LV_ANIM_OFF);
                        }
                    else {
                        lv_obj_scroll_to_view(get_focus_obj,LV_ANIM_OFF);
                        }
                    }
                else {
                    pre_focus_obj       = lv_obj_get_child(list,child_id);
                    lv_obj_clear_state(pre_focus_obj,LV_STATE_FOCUSED);

                    get_focus_obj       = lv_obj_get_child(list,child_cnt - 1);
                    lv_obj_add_state(get_focus_obj,LV_STATE_FOCUSED);

                    lv_obj_scroll_to_view(get_focus_obj,LV_ANIM_OFF);
                    }

                label               = lv_obj_get_child(pre_focus_obj,1);
                lv_label_set_long_mode(label,LV_LABEL_LONG_CLIP);

                label               = lv_obj_get_child(get_focus_obj,1);
                lv_label_set_long_mode(label,LV_LABEL_LONG_SCROLL);

                label2              = lv_obj_get_child(get_focus_obj,2);

                //sprintf(str_buf,"%s%s",lv_label_get_text(label),lv_label_get_text(label2));
                strcpy(str_buf,lv_label_get_text(label));
                strcat(str_buf,lv_label_get_text(label2));
                app_fp_play_tts_menu(str_buf);
                }
            break;

        case LV_KEY_DOWN:
            {
                if (child_cnt <= 1)
                    return;

                if (child_id != child_cnt - 1) {
                    pre_focus_obj       = lv_obj_get_child(list,child_id);
                    lv_obj_clear_state(pre_focus_obj,LV_STATE_FOCUSED);

                    get_focus_obj       = lv_obj_get_child(list,child_id + 1);
                    lv_obj_add_state(get_focus_obj,LV_STATE_FOCUSED);

                    lv_obj_scroll_to_view(get_focus_obj,LV_ANIM_OFF);
                    }
                else {
                    pre_focus_obj       = lv_obj_get_child(list,child_id);
                    lv_obj_clear_state(pre_focus_obj,LV_STATE_FOCUSED);

                    get_focus_obj       = lv_obj_get_child(list,0);
                    lv_obj_add_state(get_focus_obj,LV_STATE_FOCUSED);

                    lv_obj_scroll_to_y(list,0,LV_ANIM_OFF);
                    }

                label               = lv_obj_get_child(pre_focus_obj,1);
                lv_label_set_long_mode(label,LV_LABEL_LONG_CLIP);

                label               = lv_obj_get_child(get_focus_obj,1);
                lv_label_set_long_mode(label,LV_LABEL_LONG_SCROLL);

                label2              = lv_obj_get_child(get_focus_obj,2);

                //sprintf(str_buf,"%s%s",lv_label_get_text(label),lv_label_get_text(label2));
                strcpy(str_buf,lv_label_get_text(label));
                strcat(str_buf,";");
                strcat(str_buf,lv_label_get_text(label2));
                app_fp_play_tts_menu(str_buf);
                }
            break;

        case LV_KEY_HOME:
            {
                int32_t         ret;
                calllog_data_param_t calllog_data;
                uint32_t        index;

                get_focus_obj       = lv_obj_get_child(list,child_id);
                index               = (uint32_t) lv_obj_get_user_data(get_focus_obj);
                memset(&calllog_data,0,sizeof(calllog_data_param_t));
                ret                 = (uint32_t) calllog_data_read_number(index,&calllog_data);

                if (ret)
                    call_dial_number(calllog_data.number,calllog_data.name);

                }
            break;

        case LV_KEY_ENTER:
        case APP_KEY_VALUE_TOP_LEFT:
            {
                calllog_option_enter_param_t enter_param;

                get_focus_obj       = lv_obj_get_child(list,child_id);

                enter_param.file_tell_index = (uint32_t) lv_obj_get_user_data(get_focus_obj);
                enter_param.folder_type = p_screen_param->enter_param.folder_type;

                alv_am_win_enter(NULL,"dialed_option",&enter_param);

                }
            break;

        case APP_KEY_VALUE_TOP_RIGHT:
            {
                alv_am_win_exit_current(NULL);
                }
            break;

        case LV_KEY_END:
            alv_am_app_exit_action_all();
            break;
        }
}


