void ui_ScreenCalllogDialCalls_screen_deactive(lv_obj_t * win,void * param)
{
    list_send_win_param_t * p_param;

    p_param             = (list_send_win_param_t *) lv_obj_get_user_data(win);
    ui_screen_remind_uninit(p_param->ui_remind);
    ui_ScreenCalllogDialCalls_screen_uninit(p_param->ui_main);

    lv_mem_free(p_param);

    lv_obj_set_user_data(win,NULL);
}


void ui_ScreenCalllogDialCalls_win_focus(lv_obj_t * win,void * param)
{
    list_send_win_param_t * p_param;

    p_param             = (list_send_win_param_t *) lv_obj_get_user_data(win);
    lv_obj_t *      ui_screen = NULL;

    if (p_param->ui_main)
        ui_screen = p_param->ui_main;
    else if (p_param->ui_remind) {
        ui_screen           = p_param->ui_remind;
        }

    if (ui_screen == p_param->ui_main) {
        ui_screen_calllog_dial_calls_obj_t * p_screen_param;

        ui_screen           = p_param->ui_main;
        p_screen_param      = (ui_screen_calllog_dial_calls_obj_t *) lv_obj_get_user_data(ui_screen);

        if (p_screen_param->callog_change == 1) {
            ui_ScreenCalllogDialCalls_screen_uninit(p_param->ui_main);
            ui_screen           = ui_ScreenCalllogDialCalls_screen_init(&p_screen_param->enter_param);
            p_param->ui_main    = ui_screen;
            }

        //__inf("p_screen_param->callog_change:%d",p_screen_param->callog_change);
        }

    if (ui_screen) {
        lv_disp_load_scr(ui_screen);
        }

    if (ui_screen == p_param->ui_main) {
        lv_obj_t *      list = get_calllog_dial_calls_select_list_obj(ui_screen);

        ;
        uint32_t        child_cnt = lv_obj_get_child_cnt(list);
        uint32_t        child_id = get_list_child_focused_id(list,child_cnt);
        lv_obj_t *      get_focus_obj = NULL;
        lv_obj_t *      label,*label2;
        uint8_t         str_buf[200];

        memset(str_buf,0,200);
        get_focus_obj       = lv_obj_get_child(list,child_id);

        if (get_focus_obj) {
            label               = lv_obj_get_child(get_focus_obj,1);
            label2              = lv_obj_get_child(get_focus_obj,2);
            strcpy(str_buf,lv_label_get_text(label));
            strcat(str_buf,";");
            strcat(str_buf,lv_label_get_text(label2));

            //sprintf(str_buf,"%s%s",lv_label_get_text(label),lv_label_get_text(label2));
            app_fp_play_tts_menu(str_buf);
            }
        }
}


void ui_ScreenCalllogDialCalls_win_defocus(lv_obj_t * win,void * param)
{
    app_tts_stop();

}


uint32_t ui_ScreenCalllogDialCalls_callog_change()
{
    lv_obj_t *      app = NULL;
    lv_obj_t *      win = NULL;
    list_send_win_param_t * p_param = NULL;
    lv_obj_t *      ui_screen = NULL;

    app                 = get_app_by_name("calllog");

    if (app)
        win = get_win_by_name(app,"dial");

    if (win)
        p_param = lv_obj_get_user_data(win);

    if (p_param == NULL)
        return 0;

    if (p_param->ui_main) {
        ui_screen_calllog_dial_calls_obj_t * p_screen_param;

        ui_screen           = p_param->ui_main;
        p_screen_param      = (ui_screen_calllog_dial_calls_obj_t *) lv_obj_get_user_data(ui_screen);
        p_screen_param->callog_change = 1;

        //__inf("ui_ScreenCalllogDialCalls_callog_change");
        return 1;
        }

    return 0;
}




